private string DiscoverJoinArguments(string hostSteamId, uint appId)
{
    if (!TryParseSteam64(hostSteamId, out ulong steam64))
        return null;

    LanJoinArgs args;
    if (!LanLobbyDiscoverer.TryDiscover(steam64, appId, out args, _logger)
        || args == null
        || args.Kind == LanJoinKind.None
        || string.IsNullOrWhiteSpace(args.ConnectArguments))
        return null;

    return args.ConnectArguments.Trim();
}

